import {
	canonicalEndpointIdentity,
	expectedGet404Outcome,
	isHevyHttpError,
} from "@hevy-mcp/hevy-client";

export type ExpectedReadError = "not_found" | "end_of_list";
export type ReadCollectionEndpoint = "/v1/routines" | "/v1/workouts";
export type ReadOperationError = Error | string;

/**
 * Classify only the documented read-side 404 cases.
 *
 * This function is deliberately pure. It does not inspect mutable client
 * state, perform I/O, or convert the error, so Effect programs can use it as
 * their error-channel boundary while Promise callers retain the original
 * error object.
 */
export function classifyReadError(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
	page?: number,
): ExpectedReadError | undefined {
	if (!isHevyHttpError(error)) return undefined;
	const canonical = canonicalEndpointIdentity(error.endpoint);
	if (canonical !== endpoint && !canonical.startsWith(`${endpoint}/`)) {
		return undefined;
	}

	const expected = expectedGet404Outcome(
		error.endpoint,
		error.method,
		error.status,
		page,
	);
	if (expected === "not_found") return "not_found";
	if (expected === "end_of_list") return "end_of_list";
	return undefined;
}

export function isExpectedReadNotFound(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
): boolean {
	return classifyReadError(error, endpoint) === "not_found";
}

export function isExpectedReadEndOfList(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
	page: number,
): boolean {
	return page > 1 && classifyReadError(error, endpoint, page) === "end_of_list";
}

import { HevyHttpError } from "@hevy-mcp/hevy-client";
import { describe, expect, it } from "vitest";
import {
	classifyReadError,
	isExpectedReadEndOfList,
	isExpectedReadNotFound,
} from "./operation-errors.js";

function notFound(endpoint: string, method = "GET") {
	return new HevyHttpError("not found", {
		status: 404,
		method,
		endpoint,
	});
}

describe("classifyReadError", () => {
	it("classifies a known resource 404", () => {
		const error = notFound("/v1/routines/routine-1");

		expect(classifyReadError(error, "/v1/routines")).toBe("not_found");
		expect(isExpectedReadNotFound(error, "/v1/routines")).toBe(true);
	});

	it("classifies a later collection-page 404", () => {
		const error = notFound("/v1/workouts");

		expect(classifyReadError(error, "/v1/workouts", 2)).toBe("end_of_list");
		expect(isExpectedReadEndOfList(error, "/v1/workouts", 2)).toBe(true);
	});

	it("does not hide first-page, mutation, or unrelated 404s", () => {
		expect(
			classifyReadError(notFound("/v1/workouts"), "/v1/workouts", 1),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/workouts", "POST"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/routines/routine-1"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(new Error("network failure"), "/v1/workouts", 2),
		).toBeUndefined();
	});
});

